// A3 3.12 rule 2: whether a file's first lines carry a generator's notice, a statement that the
// file ITSELF is generated or managed by another tool. Only such a notice counts. A person's own
// rule that mentions generated files, editing or "this file" is not one, because refusing a
// person's own file is the frustration this rule must not cause in ordinary use. The table in
// `generated.test.ts` is the rule: both sides, in the forms common tools and people write.
//
// The rule, in full:
// - A notice is one of these phrases:
//   - one that starts a notice: "generated by|from|with|using", "auto-generated ...", "code
//     generated by", "generated file", "generated" alone or before "do not edit", "managed by",
//     "<tool> managed" alone ("Ansible managed"), or a bare "do not edit" (optionally "this file",
//     "manually", "directly", "by hand") that ends its sentence;
//   - one that names the file anywhere: "this file is|was|has been|gets|will be (auto-)generated,
//     regenerated, managed, synced or overwritten", "changes to this file will be lost|overwritten",
//     "this is an (auto-)generated file".
// - Where a notice starts: in a comment (TOML's `#` line, Markdown's HTML comment wherever it
//   opens, over several lines too) anywhere in it; in Markdown text, at the start of a line after
//   heading, quote and emphasis marks (never after a list bullet: a list holds the person's
//   rules), and in the first line of text that is not a list item, also after a bracket, a dash,
//   a colon, a bar or a sentence's end (a title such as "# AGENTS.md (generated by ...)").
// - Only the first 20 lines are read.

/** How many lines a notice may start in. */
export const NOTICE_LINES = 20;

const GEN = String.raw`(?:auto[- ]?|automatically\s+)?generated`;
/** What may close a phrase: emphasis marks, then the end or a punctuation mark. */
const ENDS = String.raw`(?=[*_]*\s*(?:$|[.!:;,(\[–—-]))`;
const DO_NOT_EDIT = String.raw`[^\w]+do\s+not\s+edit\b`;

/** The phrases that open a generator's notice. */
const OPENING = [
  String.raw`(?:(?:code|file|content|document)\s+)?${GEN}\s+(?:by|from|with|using|automatically)\b`,
  String.raw`${GEN}\s+(?:file|document)${ENDS}`,
  String.raw`${GEN}(?:${ENDS}|(?=${DO_NOT_EDIT}))`,
  String.raw`managed\s+by\b`,
  String.raw`[\w.-]+\s+managed(?:${ENDS}|(?=${DO_NOT_EDIT}))`,
  String.raw`do\s+not\s+(?:edit|modify)(?:\s+this\s+(?:file|document))?(?:\s+(?:manually|directly|by\s+hand))?${ENDS}`,
].join("|");

/** A notice at the start of a piece of text. */
const STARTS = new RegExp(String.raw`^(?:${OPENING})`, "iu");
/** A notice anywhere in a comment. */
const ANYWHERE = new RegExp(String.raw`(?:^|[^\w-])(?:${OPENING})`, "iu");
/** A sentence that names the file itself as generated or managed, wherever it stands. */
const ABOUT_ITSELF = new RegExp(
  [
    String.raw`\bthis\s+(?:file|document)\s+(?:is|was|has\s+been|gets|will\s+be)\s+(?:${GEN}|regenerated|managed|synced|synchronized|overwritten)\b`,
    String.raw`\b(?:changes|edits)\s+(?:to|in|made\s+to)\s+this\s+(?:file|document)\s+(?:will|may|would)\s+be\s+(?:lost|overwritten|discarded)\b`,
    String.raw`\bthis\s+is\s+an?\s+${GEN}\s+(?:file|document)\b`,
  ].join("|"),
  "iu",
);
/** A Markdown list item: the person's rules, never a generator's notice. */
const LIST_ITEM = /^\s*(?:[-*+]|\d+[.)])\s/u;
/** Where a notice may start inside a title line. */
const TITLE_BREAK = /[([]|\s[-–—|]\s|:\s|[.!?]\s/u;

/** The text after heading, quote and emphasis marks. */
const bare = (text: string): string => text.replace(/^[\s>#]*/u, "").replace(/^[*_]+(?=\S)/u, "");

const inComment = (text: string): boolean => ABOUT_ITSELF.test(text) || ANYWHERE.test(text);

function inText(text: string, title: boolean): boolean {
  if (ABOUT_ITSELF.test(text) || STARTS.test(bare(text))) return true;
  if (!title || LIST_ITEM.test(text)) return false;
  return text
    .split(TITLE_BREAK)
    .slice(1)
    .some((piece) => STARTS.test(bare(piece)));
}

/**
 * The 1-based line a generator's notice starts on in the file's first 20 lines, or undefined for
 * none. TOML's notice is a `#` comment; Markdown's is an HTML comment or the text itself (above).
 * The text is without a byte order mark.
 */
export function generatorNotice(text: string, format: "toml" | "markdown"): number | undefined {
  const lines = text
    .split("\n")
    .slice(0, NOTICE_LINES)
    .map((line) => line.replace(/\r$/u, ""));
  if (format === "toml") {
    const at = lines.findIndex((line) => {
      const trimmed = line.trim();
      return trimmed.startsWith("#") && inComment(trimmed.replace(/^#+/u, ""));
    });
    return at === -1 ? undefined : at + 1;
  }
  let comment: { start: number; text: string } | undefined;
  let titleSeen = false;
  for (const [i, line] of lines.entries()) {
    let rest = line;
    let plain = "";
    while (rest !== "") {
      if (comment !== undefined) {
        const close = rest.indexOf("-->");
        comment.text += ` ${close === -1 ? rest : rest.slice(0, close)}`;
        if (close === -1) break;
        if (inComment(comment.text)) return comment.start;
        comment = undefined;
        rest = rest.slice(close + 3);
        plain += " ";
      } else {
        const open = rest.indexOf("<!--");
        if (open === -1) {
          plain += rest;
          break;
        }
        plain += `${rest.slice(0, open)} `;
        comment = { start: i + 1, text: "" };
        rest = rest.slice(open + 4);
      }
    }
    if (plain.trim() === "") continue;
    if (inText(plain, !titleSeen)) return i + 1;
    titleSeen = true;
  }
  return comment !== undefined && inComment(comment.text) ? comment.start : undefined;
}

/** Whether the file carries a generator's notice (A3 3.12 rule 2). */
export const markedAsGenerated = (text: string, format: "toml" | "markdown"): boolean =>
  generatorNotice(text, format) !== undefined;
